import{_ as o,o as t,c as r,a2 as n}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Version History","description":"","frontmatter":{},"headers":[],"relativePath":"versionlog/versions.md","filePath":"versionlog/versions.md"}'),s={name:"versionlog/versions.md"};function a(i,e,d,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version History&quot;">​</a></h1><h3 id="current-version-2-4-0" tabindex="-1">Current version: 2.4.0 <a class="header-anchor" href="#current-version-2-4-0" aria-label="Permalink to &quot;Current version: 2.4.0&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip install --upgrade skapi</span></span></code></pre></div><p><strong>2.4.0</strong></p><p>skapi-py 2.4.0 matches skapi-js 2.4.0.</p><p>Breaking changes (removed or renamed):</p><ul><li><strong>Removed: <code>secure_request()</code>.</strong> Call your own API with <a href="/api-bridge/forward-request.html"><code>forward_request()</code></a> instead: store a key as a client secret on skapi.com, put <code>&quot;$CLIENT_SECRET&quot;</code> in a header your API checks, and send <code>&quot;skapiHeaders&quot;: True</code> to tell your API who is calling. See <a href="/api-bridge/forward-request.html#telling-the-destination-who-is-calling">Telling the destination who is calling</a>.</li><li><strong>Removed: <code>take_recovery_code()</code>.</strong> The encryption recovery code is now shown once, in <a href="/api-reference/connection.html#get-connection-info"><code>get_connection_info()</code></a> as <code>&quot;encryption_recovery&quot;</code>: the first call after the code was created returns it in <code>&quot;code&quot;</code>, and every later call returns <code>&quot;code&quot;: None</code> with a <code>&quot;message&quot;</code> saying what to do. See <a href="/database/encryption.html#encryption-recovery-codes">Encryption recovery codes</a>.</li><li><strong>Renamed: <code>regenerate_recovery_code()</code> is now <a href="/api-reference/encryption.html#regenerate-encryption-recovery-code"><code>regenerate_encryption_recovery_code()</code></a></strong>, and it returns <code>{&quot;encryptionRecoveryCode&quot;: ...}</code> instead of <code>{&quot;recoveryCode&quot;: ...}</code>.</li><li><strong>Renamed: <code>unlock_with_recovery_code()</code> is now <a href="/api-reference/encryption.html#unlock-encryption-with-recovery-code"><code>unlock_encryption_with_recovery_code()</code></a></strong>, and it returns <code>{&quot;status&quot;, &quot;repaired&quot;, &quot;encryptionRecoveryCode&quot;}</code> instead of <code>{&quot;status&quot;, &quot;repaired&quot;, &quot;recoveryCode&quot;}</code>.</li><li><strong>Removed: the <code>minPasswordLength</code> encryption option.</strong> It is no longer read. Encryption is as strong as the user&#39;s password, so ask your users for longer passwords in your own forms.</li><li><strong><code>unlock_encryption()</code> no longer sets up encryption.</strong> It only opens encryption that was set up at the user&#39;s first login with their password. For an account that never did that (for example one only ever restored from saved tokens) it raises <code>NOT_EXISTS</code>, so data is never encrypted under a mistyped password. See <a href="/database/encryption.html#unlocking">Unlocking</a>.</li></ul><p>Fixes and changes:</p><ul><li><strong>Private access keys expire after 1 hour</strong>, and skapi-py gets a new one on its own before the old one runs out. A user who loses access to a private record loses it within the hour.</li><li><strong><a href="/api-reference/database.html#delete-files"><code>delete_files()</code></a> and <code>remove_bin</code> work for any file name</strong>, including names with spaces or non-English characters, and with the <code>?t=</code> token URLs of files that are not public. They used to delete nothing for such names. See <a href="/database/files.html#deleting-files-by-url">Deleting files by URL</a>.</li><li><strong>The remembered <code>unique_id</code>s are cleaned up.</strong> After a record&#39;s <code>unique_id</code> changed, or the record was deleted (by ID, by <code>unique_id</code>, or by a query), the old <code>unique_id</code> still pointed at it in this object, so reading or writing by it reached the wrong record.</li><li><strong>Reading the next page of a read by <code>reference</code> no longer starts over at page 1.</strong></li><li><strong>Signing out or signing in as someone else clears what the previous user was handed</strong>: private access keys and remembered <code>unique_id</code>s.</li><li><strong>An expired session is kept when the network is down while it is restored.</strong> Signed-in calls raise <code>NETWORK_ERROR</code> until the network is back; the session is not signed out.</li><li><strong>One token refresh at a time.</strong> Threads that need a fresh token at the same moment share one refresh, and <code>get_profile(refresh_token=True)</code> right after restoring a session whose saved tokens had expired asks the server once instead of twice.</li><li><strong>A logout always wins over a token refresh that is still running.</strong> The refresh no longer signs the user back in, and the call that waited for it raises <code>User login is required.</code></li><li><strong>The profile includes <code>phone_number_public</code></strong> when the account has a phone number. It was always left out.</li><li><strong><a href="/api-bridge/forward-request.html"><code>forward_request()</code></a> leaves a destination&#39;s own <code>status</code>, <code>chunks</code> or <code>more</code> alone.</strong> A finished request whose answer has fields with those names (an API that replies <code>{&quot;status&quot;: &quot;pending&quot;}</code>, for example) is returned as it is, instead of being polled forever or handed to <code>on_stream</code> as streamed text. An <code>on_stream</code> callback that raises does not stop the read: a warning is shown and the read goes on.</li><li><strong>Removing access to an encrypted record re-encrypts its attached files instead of losing them.</strong> Replacing the record&#39;s key used to leave the files encrypted under the old key, so nobody could open them, the owner included.</li><li><strong><a href="/api-reference/database.html#remove-private-record-access"><code>remove_private_record_access()</code></a> on an encrypted record replaces the key first, then removes the access</strong>, so a failure leaves the access as it was. If the write that replaces the key fails, the newly encrypted file copies are deleted again.</li><li><strong>A key replaced on another device is no longer used.</strong> A grant, an update or <code>upload_files()</code> checks the record&#39;s key held in this session against the stored record first, so files and data are never encrypted under an old key.</li><li><strong>An update that does not state the <code>table</code> no longer trusts a remembered access group</strong> when it writes data: it reads the record&#39;s real group, so a record another device made non-private is not encrypted again.</li><li><strong>Large encrypted records</strong>: the newest payload file is read (older ones are tried only if it does not open), and the old ones are removed on the next update, also when the record becomes small enough not to need one.</li><li><strong>Changing the access group of an encrypted record is all or nothing.</strong> If a converted file fails to upload, the copies that did upload are removed, the change is refused, and the record keeps its original files.</li><li><strong>Two devices logging in for the first time at once</strong> no longer leave a second public key that nobody holds. Unlocking repairs an account left that way: it publishes the user&#39;s real public key again and removes the stray one. A user who pinned the stray fingerprint gets <code>ENCRYPTION_PEER_KEY_CHANGED</code> and must pin the new one.</li><li><strong><code>lock_encryption()</code> keeps an encryption recovery code that was not collected yet</strong>: the next <code>get_connection_info()</code> still returns it, once. A logout drops it.</li><li><strong>Reads made by other threads during a grant or a revoke get decrypted data.</strong> They could receive the raw encrypted data.</li></ul><p><strong>2.3.0</strong></p><ul><li>First release of skapi-py, the Python version of skapi-js 2.3.0.</li></ul>',11)])])}const g=o(s,[["render",a]]);export{p as __pageData,g as default};
